<?php

declare(strict_types=1);

namespace Kestello\Cms\Hooks;

/**
 * The hook reference page of the docs, as Markdown. Generated, so it always
 * matches the code: `php bin/cms hooks:list --markdown > hooks.md`.
 *
 * @internal HooksListCommand
 */
final class HookReference
{
    /** @param list<Hook> $hooks */
    public static function markdown(array $hooks, string $version): string
    {
        $out = ['# Hook reference', '',
            "<!-- Generated by `php bin/cms hooks:list --markdown` from Kestello {$version}. Edit the code, not this page. -->", '',
            'Every event and filter Kestello offers to plugins and themes, with the version it appeared in. [Events and filters](/developers/events) explains how to listen to them and the [deprecation policy](/developers/events#compatibility-and-deprecation) says how long a hook keeps working once it is replaced.', '',
            'Events are in the namespace shown under each name. Filter callbacks receive the value first, then the arguments in the order listed, and return the value.', ''];

        foreach ([Hook::EVENT => 'Events', Hook::FILTER => 'Filters'] as $kind => $title) {
            $list = array_values(array_filter($hooks, static fn(Hook $h) => $h->kind === $kind));
            if ($list === []) {
                continue;
            }
            $out[] = "## {$title}";
            $out[] = '';
            $group = null;
            foreach ($list as $hook) {
                $heading = ($hook->owner === 'core' ? '' : self::ownerLabel($hook->owner) . ': ') . $hook->group;
                if ($heading !== $group) {
                    $out[] = "### {$heading}";
                    $out[] = '';
                    $group = $heading;
                }
                array_push($out, ...($kind === Hook::EVENT ? self::event($hook) : self::filter($hook)));
            }
        }

        return implode("\n", $out);
    }

    /** @return list<string> */
    private static function event(Hook $hook): array
    {
        $lines = ['#### ' . $hook->shortName(), '', '`' . $hook->name . '`, since ' . $hook->since . ($hook->stoppable ? '. Listeners can stop the ones after them.' : '.'), ''];
        array_push($lines, ...self::deprecation($hook));
        if ($hook->description !== '') {
            $lines[] = self::text($hook->description);
            $lines[] = '';
        }
        if ($hook->properties !== []) {
            $lines[] = '| Property | Type | Description |';
            $lines[] = '|---|---|---|';
            foreach ($hook->properties as $name => $p) {
                $lines[] = '| `$' . $name . '` | `' . $p['type'] . '` | ' . self::cell($p['description']) . ' |';
            }
            $lines[] = '';
        }

        return $lines;
    }

    /** @return list<string> */
    private static function filter(Hook $hook): array
    {
        // VitePress reads a trailing {...} in a heading as attributes; give names with a {part} an explicit anchor.
        $anchor = str_contains($hook->name, '{') ? ' {#' . trim((string) preg_replace('/[^a-z0-9]+/', '-', $hook->name), '-') . '}' : '';
        $lines = ['#### `' . $hook->name . '`' . $anchor, '', 'Since ' . $hook->since . '. The value is `' . $hook->value . '`.', ''];
        array_push($lines, ...self::deprecation($hook));
        $lines[] = self::text($hook->description);
        $lines[] = '';
        if ($hook->arguments !== []) {
            $lines[] = '| Argument | Description |';
            $lines[] = '|---|---|';
            foreach ($hook->arguments as $signature => $description) {
                $lines[] = '| `' . $signature . '` | ' . self::cell($description) . ' |';
            }
            $lines[] = '';
        }

        return $lines;
    }

    /** @return list<string> */
    private static function deprecation(Hook $hook): array
    {
        if ($hook->deprecated === null) {
            return [];
        }
        $d = $hook->deprecated;
        $line = '::: warning Deprecated' . "\n" . 'Deprecated in ' . $d['since']
            . ($d['removal'] !== null ? ', removed in ' . $d['removal'] : '') . '.'
            . ($d['use'] !== null ? ' Use `' . $d['use'] . '` instead.' : '') . "\n:::";

        return [$line, ''];
    }

    private static function ownerLabel(string $owner): string
    {
        [$type, $slug] = array_pad(explode(':', $owner, 2), 2, '');

        return ucfirst($type) . ' ' . $slug;
    }

    /** Words that look like markup or code (<head>, $user, #[Queued]) are shown as code. */
    private static function text(string $text): string
    {
        $parts = explode('`', $text);
        foreach ($parts as $i => $part) {
            if ($i % 2 === 0) {        // outside `code`
                $parts[$i] = (string) preg_replace(['/(?<!\w)(<\/?[a-z]+>)/', '/(?<!\w)(\$[a-zA-Z_]+)/', '/(?<!\w)(#\[\w+\])/'], ['`$1`', '`$1`', '`$1`'], $part);
            }
        }

        return implode('`', $parts);
    }

    private static function cell(string $text): string
    {
        return str_replace('|', '\\|', self::text($text));
    }
}
